parameters.jsCode:
const data = $json;

const partnerId =
  data.partner_id ??
  data.id ??
  data.res_partner_id ??
  null;

if (partnerId === null || partnerId === undefined || partnerId === '') {
  throw new Error('PARTNER_ID_MISSING: Unable to determine unified Odoo res.partner ID.');
}

return [{
  json: {
    ...data,
    partner_id: partnerId,
    partner_resolution: 'RESOLVED'
  }
}];

